package com.shipflow.store.api;
import com.shipflow.common.api.ApiResponse; import com.shipflow.store.api.model.*; import com.shipflow.store.application.StoreApplicationService; import com.shipflow.store.domain.model.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/stores") public class StoreController {private final StoreApplicationService service; public StoreController(StoreApplicationService s){service=s;} private Long tenant(Jwt j){return Long.valueOf(j.getClaimAsString("tenant_id"));} private Long user(Jwt j){return Long.valueOf(j.getSubject());}
 @PostMapping public ResponseEntity<ApiResponse<Store>> create(@Valid @RequestBody CreateStoreRequest r,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.create(tenant(j),r,k,user(j),q)));}
 @GetMapping public ApiResponse<StorePage> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String status,@RequestParam(required=false)String platformCode,@AuthenticationPrincipal Jwt j){return ApiResponse.success(service.page(tenant(j),status,platformCode,page,pageSize));}
 @GetMapping("/{id}") public ApiResponse<Store> get(@PathVariable Long id,@AuthenticationPrincipal Jwt j){return ApiResponse.success(service.get(tenant(j),id));}
 @PutMapping("/{id}") public ApiResponse<Store> update(@PathVariable Long id,@Valid @RequestBody UpdateStoreRequest r,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ApiResponse.success(service.update(tenant(j),id,r,user(j),q));}
 @PostMapping("/{id}/status") public ApiResponse<Store> status(@PathVariable Long id,@Valid @RequestBody StoreStatusChangeRequest r,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ApiResponse.success(service.status(tenant(j),id,r,user(j),q));}}
